import {chaosBadge,footStamp,frogStampColor,votersFor} from './lobby-visuals';
import {gravityClock} from '../chaos/extreme-chaos';
import {swapClock} from '../chaos/swap-clock';
import {modifier,type ModifierId} from '../chaos/registry';
import type {Connection} from '../network/client';
import './chaos-ui.css';
/** Screen-space presentation only; no touch/viewport ownership changes. */
export class ChaosUI{
 gravityIndicator=document.createElement('div');swapIndicator=document.createElement('div');panel=document.createElement('section');strip=document.createElement('div');toggle=document.createElement('button');signature='';
 constructor(private net:Connection){this.gravityIndicator.id='chaos-gravity-clock';this.gravityIndicator.hidden=true;this.gravityIndicator.setAttribute('role','status');this.gravityIndicator.setAttribute('aria-live','polite');document.querySelector('#session')!.append(this.gravityIndicator);this.swapIndicator.id='chaos-swap-clock';this.swapIndicator.hidden=true;this.swapIndicator.setAttribute('role','timer');this.swapIndicator.title='Swaps repeat every 12 seconds. Your partner is marked before the swap.';document.querySelector('#session')!.append(this.swapIndicator);this.panel.id='chaos-voting';this.panel.hidden=true;this.panel.setAttribute('aria-label','Chaos Voting');document.querySelector('#results')!.after(this.panel);this.strip.id='chaos-active';document.querySelector('#session')!.append(this.strip);this.toggle.id='chaos-toggle';this.toggle.innerHTML=chaosBadge+'<span class="chaos-toggle-label"></span>';this.toggle.onclick=()=>net.room?.send('select-chaos',!net.lobby?.chaosEnabled);document.querySelector('.lobby-primary')!.after(this.toggle);const note=document.createElement('p');note.className='chaos-lobby-note';note.textContent='Round 1 is normal. Vote between rounds; up to 3 effects rotate. Changing Chaos clears Ready.';this.toggle.after(note);}
 update(){const {lobby,chaos:c,playerId,status}=this.net;const toggleLabel=`Chaos Voting: ${lobby?.chaosEnabled===false?'Off':'On'}`;this.toggle.querySelector('.chaos-toggle-label')!.textContent=toggleLabel;this.toggle.setAttribute('aria-label',toggleLabel);this.toggle.setAttribute('aria-pressed',String(lobby?.chaosEnabled!==false));this.toggle.disabled=!lobby||lobby.phase!=='lobby'||lobby.hostId!==playerId||status!=='connected';
  const voting=lobby?.phase==='game'&&!!c&&c.phase!=='idle';this.panel.hidden=!voting;this.strip.hidden=lobby?.phase!=='game'||!c?.enabled;this.strip.textContent=c?.enabled?(c.active.length?`CHAOS · ${c.active.map(id=>modifier(id).name).join(' + ')}`:'CHAOS · Round 1: normal physics'):'';
  const snapshot=this.net.snapshots.at(-1)?.state,social=snapshot?.frogChaos;this.swapIndicator.hidden=!(lobby?.phase==='game'&&c?.active.includes('swap_hop')&&social&&this.net.outbreak?.phase==='playing');if(!this.swapIndicator.hidden&&snapshot&&social){const clock=swapClock(snapshot.tick,social.start);this.swapIndicator.textContent=`⇄ SWAP IN ${clock.seconds}s`;this.swapIndicator.dataset.urgent=String(clock.urgent);}
  const extreme=snapshot?.extremeChaos;this.gravityIndicator.hidden=!(lobby?.phase==='game'&&c?.active.includes('gravity_flip')&&extreme&&this.net.outbreak?.phase==='playing');if(!this.gravityIndicator.hidden&&snapshot&&extreme){const clock=gravityClock(snapshot.tick,extreme.start),arrow=extreme.direction===1?'↓':'↑',next=extreme.direction===1?'↑ UP':'↓ DOWN';this.gravityIndicator.textContent=clock.warning?`⚠ GRAVITY FLIPS ${next} IN ${clock.seconds}s`:`${arrow} GRAVITY ${extreme.direction===1?'DOWN':'UP'} · FLIP IN ${clock.seconds}s`;this.gravityIndicator.dataset.warning=String(clock.warning);}
  if(!voting||!c)return;document.querySelector<HTMLElement>('#results')!.hidden=true;document.querySelector<HTMLElement>('#session')!.hidden=true;
  const signature=JSON.stringify([c,playerId,status,lobby?.players.map(p=>[p.id,p.name,p.connected,p.appearance])]);if(signature!==this.signature){this.signature=signature;this.panel.replaceChildren();const heading=document.createElement('h2');heading.textContent=c.phase==='voting'?'Choose the next chaos':'The pond has spoken!';this.panel.append(heading);const timer=document.createElement('strong');timer.id='chaos-timer';this.panel.append(timer);
