 update(){const {lobby,chaos:c,playerId,status}=this.net;this.toggle.textContent=`Chaos Voting: ${lobby?.chaosEnabled===false?'Off':'On'}`;this.toggle.setAttribute('aria-pressed',String(lobby?.chaosEnabled!==false));this.toggle.disabled=!lobby||lobby.phase!=='lobby'||lobby.hostId!==playerId||status!=='connected';
