   const keeping=document.createElement('p');keeping.textContent=`Keeping: ${c.active.filter(id=>c.phase==='reveal'||id!==c.expiring).map(id=>modifier(id).name).join(' + ')||'normal physics'}`;this.panel.append(keeping);
